'use strict';

// MODULES //

import numelDimension from '@stdlib/ndarray-base-numel-dimension';
import getStrides from '@stdlib/ndarray-base-strides';
import getStride from '@stdlib/ndarray-base-stride';
import getOffset from '@stdlib/ndarray-base-offset';
import getData from '@stdlib/ndarray-base-data-buffer';
import { ndarray as strided } from '@stdlib/blas-ext-base-dcartesian-product';


// MAIN //

/**
* Computes the Cartesian product for two double-precision floating-point ndarrays.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional input ndarray.
*     -   a two-dimensional output ndarray.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {Object} output ndarray
*
* @example
* import Float64Vector from '@stdlib/ndarray-vector-float64';
* import zeros from '@stdlib/ndarray-zeros';
*
* var x = new Float64Vector( [ 1.0, 2.0 ] );
* var y = new Float64Vector( [ 3.0, 4.0 ] );
* var out = zeros( [ 4, 2 ], {
*     'dtype': 'float64'
* });
*
* var v = dcartesianProduct( [ x, y, out ] );
* // returns <ndarray>[ [ 1.0, 3.0 ], [ 1.0, 4.0 ], [ 2.0, 3.0 ], [ 2.0, 4.0 ] ]
*
* var bool = ( v === out );
* // returns true
*/
function dcartesianProduct( arrays ) {
	var out;
	var so;
	var x;
	var y;

	x = arrays[ 0 ];
	y = arrays[ 1 ];
	out = arrays[ 2 ];

	so = getStrides( out, false );

	strided( numelDimension( x, 0 ), numelDimension( y, 0 ), getData( x ), getStride( x, 0 ), getOffset( x ), getData( y ), getStride( y, 0 ), getOffset( y ), getData( out ), so[ 0 ], so[ 1 ], getOffset( out ) ); // eslint-disable-line max-len
	return out;
}


// EXPORTS //

export default dcartesianProduct;
